<style>
/* Deliberately plain admin styling: flat surfaces, one accent colour, and no decorative effects. */
.ap-studio{--ap-bg:#0f172a;--ap-line:#334155;--ap-text:#f8fafc;--ap-muted:#94a3b8;--ap-primary:#4f46e5;background:#0f172a;border:1px solid #334155;border-radius:.5rem;padding:1.5rem;box-shadow:none}
.ap-header{padding-bottom:1.25rem}.ap-brand-mark{width:2.35rem;height:2.35rem;background:#4f46e5;border-radius:.4rem}.ap-brand p,.ap-kicker{color:#94a3b8;letter-spacing:.08em}.ap-brand h1{font-size:1.05rem}.ap-button{border-radius:.35rem;min-height:2.35rem;transition:background-color .15s ease,border-color .15s ease}.ap-button-primary{background:#4f46e5}.ap-button-primary:hover{background:#4338ca;filter:none;transform:none}.ap-button-quiet{background:#172033;border-color:#475569}.ap-button-quiet:hover{background:#253247;border-color:#64748b}.ap-button-preview{background:#e2e8f0;color:#0f172a}.ap-button-danger{border-color:#9f1239;background:#4c0519;color:#fecdd3}
.ap-tabs{gap:.25rem;margin-bottom:1.25rem;padding-bottom:.55rem}.ap-tab{border-radius:.3rem;padding:.58rem .7rem}.ap-tab:hover{background:#1e293b}.ap-tab.is-active{background:#4f46e5;box-shadow:none}.ap-tab.is-active span{background:#c7d2fe;color:#312e81}.ap-welcome{align-items:center;padding:1.35rem 1.5rem;background:#172033;border:1px solid #334155;border-radius:.5rem}.ap-welcome h2,.ap-panel-heading h2{font-size:1.45rem;letter-spacing:-.02em}.ap-welcome p:not(.ap-kicker),.ap-panel-heading p{color:#94a3b8}.ap-stats{gap:.75rem;margin:.75rem 0}.ap-stats article,.ap-card,.ap-empty,.ap-item{background:#172033;border-color:#334155;border-radius:.5rem}.ap-stats article{min-height:7rem;padding:1rem}.ap-stats article>svg{position:static;width:1.2rem;height:1.2rem;margin-bottom:.7rem;color:#a5b4fc}.ap-stats strong{font-size:1.35rem;letter-spacing:0}.ap-card{padding:1.25rem}.ap-guide{align-items:center}.ap-guide-links button{color:#c7d2fe;text-decoration:underline;text-underline-offset:3px}.ap-count{border-radius:.3rem}.ap-panel.is-active{animation:none}.ap-form input,.ap-form select,.ap-form textarea{background:#0f172a;border-color:#475569;border-radius:.35rem}.ap-form input:focus,.ap-form select:focus,.ap-form textarea:focus{border-color:#818cf8;box-shadow:0 0 0 .15rem #818cf833}.ap-fieldset{border-color:#475569;border-radius:.35rem}.ap-avatar-preview{background:#0f172a;border-color:#475569;border-radius:.4rem}.ap-upload{border-color:#64748b;border-radius:.35rem}.ap-colours label{background:#0f172a;border-color:#475569;border-radius:.35rem}.ap-item summary{padding:.9rem 1rem}.ap-item-body{padding:1rem}.ap-empty{padding:2.25rem 1rem}.ap-empty strong{color:#f8fafc}@media(max-width:600px){.ap-studio{padding:1rem;border-radius:0;border-inline:0}.ap-welcome{padding:1.1rem}}
</style>
<script>
(() => { const selector = document.querySelector('[data-advanced-studio] select[name="template_key"]'); if (!selector) return; const current = <?= json_encode((string) ($portfolio['template_key'] ?? 'classic')) ?>; const templates = <?= json_encode($templates ?? [], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) ?>; Object.entries(templates).forEach(([value, label]) => { if (!selector.querySelector('option[value="' + value + '"]')) selector.add(new Option(label, value)); }); selector.value = current; })();
</script>
<script>
(() => { const studio = document.querySelector('[data-advanced-studio]'); if (!studio) return; const valid = new Set([...studio.querySelectorAll('[data-ap-tab-panel]')].map(el => el.dataset.apTabPanel)); const url = new URL(window.location.href); const activate = tab => { tab = valid.has(tab) ? tab : 'overview'; studio.querySelectorAll('[data-ap-tab-panel]').forEach(el => el.classList.toggle('is-active', el.dataset.apTabPanel === tab)); studio.querySelectorAll('[data-ap-tab-button]').forEach(el => el.classList.toggle('is-active', el.dataset.apTabButton === tab)); url.searchParams.set('tab', tab); history.replaceState({}, '', url); if (window.lucide) window.lucide.createIcons(); }; studio.querySelectorAll('[data-ap-tab-button]').forEach(button => button.addEventListener('click', () => activate(button.dataset.apTabButton))); activate(url.searchParams.get('tab') || 'overview'); })();
</script>
